item.command:
/bin/bash -lc "sudo mkdir -p /etc/opt/chrome/policies/managed
sudo sh -c 'printf \"%s\\n\" \"{\\\"DefaultFontSize\\\":24,\\\"DefaultFixedFontSize\\\":24}\" > /etc/opt/chrome/policies/managed/default-font-size.json'
node <<'NODE'
const fs = require('fs');
const path = process.env.HOME + '/.config/google-chrome/Default/Preferences';
const prefs = JSON.parse(fs.readFileSync(path, 'utf8'));
prefs.webkit ||= {};
prefs.webkit.webprefs ||= {};
prefs.webkit.webprefs.default_font_size = 24;
prefs.webkit.webprefs.default_fixed_font_size = 24;
const tmp = path + '.tmp-font-size';
fs.writeFileSync(tmp, JSON.stringify(prefs));
fs.renameSync(tmp, path);
NODE
node -e \"const fs=require('fs'); const p=process.env.HOME+'/.config/google-chrome/Default/Preferences'; const j=JSON.parse(fs.readFileSync(p,'utf8')); console.log(JSON.stringify(j.webkit.webprefs,null,2));\"
sudo cat /etc/opt/chrome/policies/managed/default-font-size.json"

